#!/bin/sh
# Creates .env with freshly generated secrets, so a deployment is:
#
#   ./setup.sh you@example.com
#   docker compose up -d --build
#
# Safe to re-run: it never overwrites an existing .env.
set -eu
cd "$(dirname "$0")"

if [ -f .env ]; then
  echo ".env already exists - leaving it untouched."
  exit 0
fi

# N random bytes as hex (no openssl needed; works on Linux and macOS)
rand() { head -c "$1" /dev/urandom | od -An -tx1 | tr -d ' \n'; }

ADMIN_EMAIL="${1:-admin@example.com}"
ADMIN_PASSWORD="$(rand 9)"

umask 077 # secrets: readable by you only
cat > .env <<EOF
# Generated by setup.sh on $(date -u +%Y-%m-%dT%H:%M:%SZ). See .env.example for all options.
JWT_SECRET=$(rand 32)
MONGO_ROOT_PASSWORD=$(rand 16)
ADMIN_EMAIL=$ADMIN_EMAIL
ADMIN_PASSWORD=$ADMIN_PASSWORD
HTTP_PORT=8080
EOF

echo "Created .env with random secrets."
echo
echo "  Admin login:  $ADMIN_EMAIL"
echo "  Password:     $ADMIN_PASSWORD"
echo
echo "Next:  docker compose up -d --build"
echo "Then:  open http://localhost:8080  (admin panel: /admin)"
